css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuento{display: flex; gap: 6px; align-items: center; justify-content: center;}
.mz .palote5{width: 30px; height: 26px;}
.mz .palote1{width: 9px; height: 26px;}
.mz .palote5 line,.mz .palote1 line{stroke: #000; stroke-width: 2.5; stroke-linecap: round;}
.mz .pista-palotes{font-size: 11.5px; margin-bottom: 6px; display: flex; align-items: center; gap: 8px;}
.mz .pista-palotes .recuento{justify-content: flex-start;}
.mz .e1-wrap{display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center;}
.mz .mosaico{border: 2px solid var(--bosque); border-radius: 10px; padding: 10px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; justify-items: center; align-items: center;}
.mz .mosaico svg{width: 36px; height: 36px;}
.mz .tabla-rellenar{border-collapse: collapse; font-size: 13px; width: 100%;}
.mz .tabla-rellenar th,.mz .tabla-rellenar td{border: 1.5px solid var(--bosque); padding: 5px 10px; text-align: center; font-weight: 700;}
.mz .tabla-rellenar th{background: #f3f3f3; font-size: 11px; font-family: sans-serif;}
.mz .tabla-rellenar svg{width: 26px; height: 26px; vertical-align: middle;}
.mz .tabla-rellenar .celda-recuento{min-width: 130px; height: 34px;}
.mz .tabla-rellenar .celda-num{min-width: 52px; height: 34px;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .preg-fila{font-size: 12.5px; line-height: 1.4;}
.mz .preg-hueco{display: inline-block; min-width: 44px; border-bottom: 1.5px solid var(--bosque); height: 19px; vertical-align: middle; margin-left: 4px;}
.mz .preg-hueco-grande{display: inline-block; min-width: 95px; border-bottom: 1.5px solid var(--bosque); height: 19px; vertical-align: middle; margin-left: 4px;}
.mz .preg-lista-2col{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 18px;}
.mz .tabla-doble{border-collapse: collapse; font-size: 13px; margin: 0 auto 7px;}
.mz .tabla-doble th,.mz .tabla-doble td{border: 1.5px solid var(--bosque); padding: 6px 16px; text-align: center; font-weight: 700;}
.mz .tabla-doble th{background: #f3f3f3; font-size: 11px; font-family: sans-serif;}
.mz .tabla-doble .fila-nombre{font-size: 12.5px; background: #fafafa;}
.mz .tabla-doble .celda-total{min-width: 62px; height: 30px;}
.mz .ordenar-puestos{display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; align-items: center;}
.mz .ordenar-puesto{display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .ordenar-num{font-family: sans-serif; font-size: 11.5px; font-weight: 700; color: #555;}
.mz .ordenar-hueco{width: 100%; height: 40px; border: 1.5px solid var(--bosque); border-radius: 8px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .vf-fila{display: flex; justify-content: space-between; align-items: center; border: 1.5px solid var(--bosque); border-radius: 999px; padding: 4px 8px 4px 14px; font-size: 12.5px;}
.mz .vf-opciones{display: flex; gap: 8px;}
.mz .vf-circ{width: 26px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 12.5px; font-family: sans-serif;}
.mz .preg-fila{line-height: 1.725 !important;}
